import React, { useState, useEffect } from "react";
import { useNavigate, useLocation } from "react-router-dom";
import { collection, getDocs, query, where } from "firebase/firestore";
import { db } from "../../firebaseConfig";
import './ExamPage.css';

const ExamPage = () => {
  const [timeLeft, setTimeLeft] = useState(300); // 5 minutes timer (300 seconds)
  const [questions, setQuestions] = useState([]);
  const [answers, setAnswers] = useState({});
  const [loading, setLoading] = useState(true);
  const navigate = useNavigate();
  const location = useLocation();

  // Assuming student class and subject are passed via navigation state
  const { studentClass, subject } = location.state || {};

  useEffect(() => {
    // Fetch exam questions based on studentClass and subject
    const fetchQuestions = async () => {
      try {
        const questionsCollectionRef = collection(db, "exams");
        const q = query(
          questionsCollectionRef,
          where("class", "==", studentClass),
          where("subject", "==", subject)
        );
        const querySnapshot = await getDocs(q);
        const fetchedQuestions = querySnapshot.docs.map((doc) => ({
          id: doc.id,
          ...doc.data(),
        }));

        setQuestions(fetchedQuestions);
        setAnswers(
          fetchedQuestions.reduce((acc, question) => {
            acc[question.id] = ""; // Initialize answers with empty strings
            return acc;
          }, {})
        );
        setLoading(false);
      } catch (error) {
        console.error("Error fetching questions:", error);
      }
    };

    fetchQuestions();
  }, [studentClass, subject]);

  useEffect(() => {
    if (timeLeft === 0) return;

    const timer = setInterval(() => {
      setTimeLeft((prevTime) => prevTime - 1);
    }, 1000);

    return () => clearInterval(timer);
  }, [timeLeft]);

  const calculateScore = () => {
    let score = 0;

    questions.forEach((question) => {
      if (
        answers[question.id]?.trim().toLowerCase() ===
        question.correctAnswer?.trim().toLowerCase()
      ) {
        score += 100 / questions.length; // Divide equally among all questions
      }
    });

    return Math.round(score);
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    const score = calculateScore();
    navigate("/view-scores", { state: { score } });
  };

  const handleChange = (e, questionId) => {
    setAnswers({
      ...answers,
      [questionId]: e.target.value,
    });
  };

  if (loading) {
    return <div>Loading questions...</div>;
  }

  return (
    <div className="exam-container">
      <h2>Exam - {subject}</h2>
      <div className="timer">
        <p>
          Time Left: {Math.floor(timeLeft / 60)}:{timeLeft % 60}
        </p>
      </div>

      <form onSubmit={handleSubmit} className="exam-form">
        {questions.map((question) => (
          <div className="question" key={question.id}>
            <label>{question.text}</label>
            <input
              type="text"
              value={answers[question.id] || ""}
              onChange={(e) => handleChange(e, question.id)}
              required
            />
          </div>
        ))}

        <button type="submit" className="submit-btn">
          Submit Exam
        </button>
      </form>
    </div>
  );
};

export default ExamPage;
